def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Detect 3x3 ring motifs whose center is a 2.
    motifs = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 2:
                continue
            if all(grid[rr][cc] == 3
                   for rr, cc in ((r-1,c-1),(r-1,c),(r-1,c+1),
                                  (r,c-1),(r,c+1),
                                  (r+1,c-1),(r+1,c),(r+1,c+1))):
                motifs.append((r, c))
    if not motifs:
        return out
    # The divider lines through motif centers are projected across the
    # background: fill their center rows, and copy the ring's side pixels
    # beside each other parallel divider.
    vertical = {c for _, c in motifs}
    horizontal = {r for r, _ in motifs}
    # Include full straight divider lines (2s) even when no motif is on them.
    vertical.update(c for c in range(w) if all(grid[r][c] == 2 for r in range(h)))
    horizontal.update(r for r in range(h) if all(v == 2 for v in grid[r]))
    for r, c in motifs:
        for cc in range(w):
            if out[r][cc] == 0:
                out[r][cc] = 1
        for rr in (r-1, r+1):
            if 0 <= rr < h:
                for line in vertical:
                    if line == c:
                        continue
                    for cc in (line-1, line+1):
                        if 0 <= cc < w and out[rr][cc] == 0:
                            out[rr][cc] = 1
        # Symmetric handling for horizontal dividers, as in transposed tasks.
        for cc in (c-1, c+1):
            if 0 <= cc < w:
                for line in horizontal:
                    if line == r:
                        continue
                    for rr in (line-1, line+1):
                        if 0 <= rr < h and out[rr][cc] == 0:
                            out[rr][cc] = 1
    return out
